// registryCleanupCommands contains executable code only from this compile-time
// constant. The key, generation and presentation preference travel as JSON data.
// The caller records each complete command's UTF-16LE bytes INCLUDING its NUL.
func registryCleanupCommands(key, ticket string) (normal, quiet string, err error) {
	if _, _, err = registrationMutexSpec("S-1-5-18", key); err != nil {
		return "", "", err
	}
	if len(ticket) != 64 || strings.Trim(ticket, "0123456789abcdef") != "" {
		return "", "", errors.New("invalid cleanup generation")
	}
	path, err := systemPowerShell()
	if err != nil {
		return "", "", err
	}
	var compressed bytes.Buffer
	z, err := gzip.NewWriterLevel(&compressed, gzip.BestCompression)
	if err != nil {
		return "", "", err
	}
	if _, err = z.Write([]byte(registryCleanupPowerShell)); err != nil {
		return "", "", err
	}
	if err = z.Close(); err != nil {
		return "", "", err
	}
	// Each compressed byte maps to U+0100..U+01FF, an inert quoted literal
	// alphabet. This avoids a second base64 expansion inside EncodedCommand.
	staticWords := make([]rune, compressed.Len())
	for i, b := range compressed.Bytes() {
		staticWords[i] = rune(b) + 0x100
	}
	static := string(staticWords)
	build := func(silent bool) (string, error) {
		data, e := json.Marshal(struct {
			Key    string `json:"key"`
			Ticket string `json:"ticket"`
			Quiet  bool   `json:"quiet"`
		}{key, ticket, silent})
		if e != nil {
			return "", e
		}
		loader := "$bootstrap='" + base64.StdEncoding.EncodeToString(data) + "';$parentData=$env:CUDIA_CLEANUP_PARENT_DATA;[Environment]::SetEnvironmentVariable('CUDIA_CLEANUP_PARENT_DATA',$null,'Process');$b=[byte[]]('" + static + "'.ToCharArray()|%{[int]$_-256});$m=New-Object IO.MemoryStream(,$b);$g=New-Object IO.Compression.GZipStream($m,[IO.Compression.CompressionMode]::Decompress);$r=New-Object IO.StreamReader($g,[Text.Encoding]::UTF8);$s=$r.ReadToEnd();$r.Dispose();& ([ScriptBlock]::Create($s))"
		words := utf16.Encode([]rune(loader))
		raw := make([]byte, len(words)*2)
		for i, word := range words {
			binary.LittleEndian.PutUint16(raw[2*i:], word)
		}
		command := `"` + path + `" -NoLogo -NoProfile -NonInteractive -EncodedCommand ` + base64.StdEncoding.EncodeToString(raw)
		if len(utf16.Encode([]rune(command)))+1 > 32500 {
			return "", errors.New("bounded cleanup command exceeds Windows command-line limit")
		}
		return command, nil
	}
	if normal, err = build(false); err != nil {
		return "", "", err
	}
	if quiet, err = build(true); err != nil {
		return "", "", err
	}
	return normal, quiet, nil
}

